/// Whether `path` is one of the analyzer configuration files directly in this graph's
/// workspace directory. A same-basename file below it is ordinary project content and must
/// not force a project reload.
pub(crate) fn is_workspace_config_path(&self, path: &Path) -> bool {
    let Some(workspace) = self.workspace_root.as_deref() else { return false };
    if !path
        .file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| project_model::CONFIG_FILE_NAMES.contains(&name))
    {
        return false;
    }
    let Some(parent) = path.parent() else { return false };
    parent == workspace
        || match (std::fs::canonicalize(parent), std::fs::canonicalize(workspace)) {
            (Ok(parent), Ok(workspace)) => parent == workspace,
            _ => false,
        }
}

/// Force a full project reload after the workspace-root analyzer configuration changed.
