/// A semantic-fingerprint-equal publication still requests the root-layout comparison:
/// declared aliases are not part of GraphFp, so topology equality cannot prove root identity.
#[test]
fn every_publication_requests_a_search_root_check() {
    let requested = Arc::new(AtomicUsize::new(0));
    let hook = {
        let requested = Arc::clone(&requested);
        Arc::new(move |signal: GraphPublishSignal| {
            if signal.roots_refresh_requested {
                requested.fetch_add(1, Ordering::SeqCst);
            }
            GraphPublishOutcome::ALL_HANDLED
        })
    };
    let graph = GraphState::disabled().with_publish_hook(hook);

    graph.notify_published(0, false);
    graph.notify_published(0, false);

    assert_eq!(requested.load(Ordering::SeqCst), 2);
}

/// A daemon whose workspace was taken over by a newer generation must not build the

/// Root and topology failures retain different obligations and flush with different signals.
#[test]
fn root_and_topology_retries_are_independent() {
    let signals = Arc::new(Mutex::new(Vec::new()));
    let fail_roots = Arc::new(AtomicBool::new(true));
    let hook = {
        let signals = Arc::clone(&signals);
        let fail_roots = Arc::clone(&fail_roots);
        Arc::new(move |signal: GraphPublishSignal| {
            signals
                .lock()
                .unwrap()
                .push((signal.topology_changed, signal.roots_refresh_requested));
            GraphPublishOutcome {
                topology_handled: true,
                roots_handled: !fail_roots.swap(false, Ordering::SeqCst),
            }
        })
    };
    let graph = GraphState::disabled().with_publish_hook(hook);
    {
        let mut inner = lock_recover(&graph.inner);
        inner.status = GraphStatus::Ready { files: 0 };
        inner.published = Some(Published {
            stale: false,
            generation: 1,
            fingerprint: crate::graph_db::GraphFp::default(),
            reload: ReloadState::Idle,
            force_stale: false,
        });
    }

    graph.notify_published(0, false);
    assert!(graph.pending_search_roots_refresh.load(Ordering::SeqCst));
    assert!(!graph.pending_topology_refresh.load(Ordering::SeqCst));
    graph.flush_pending_search_roots_refresh();

    assert_eq!(
        signals.lock().unwrap().as_slice(),
        &[(false, true), (false, true)],
        "root retry never masquerades as a topology refresh",
    );
    assert!(!graph.pending_search_roots_refresh.load(Ordering::SeqCst));
}

