/// A workspace-root config rewrite can preserve GraphFp (the declared path alias resolves to
/// the same source tree), but it still requires a full publication for search-root identity.
#[test]
fn project_config_reload_bypasses_equal_fingerprint_and_publishes_full() {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    let source = root.join("cf");
    sample_workspace(&source);
    fs::write(root.join("bsl-analyzer.toml"), "[source]\nroot = \"cf\"\n").unwrap();

    let graph = GraphState::for_workspace(root.to_path_buf());
    graph.ensure_loading();
    wait_ready(&graph);
    let (before_generation, before_fp) = {
        let inner = lock_recover(&graph.inner);
        let published = inner.published.as_ref().unwrap();
        (published.generation, published.fingerprint)
    };

    fs::write(root.join("bsl-analyzer.toml"), "[source]\nroot = \"./cf\"\n").unwrap();
    assert_eq!(
        graph.current_disk_fp().unwrap().0,
        before_fp,
        "the alias-only config edit is deliberately invisible to GraphFp",
    );
    assert_eq!(graph.nudge_project_reload(), NudgeOutcome::ReloadClaimed);
    wait_for(|| {
        lock_recover(&graph.inner).published.as_ref().is_some_and(|published| {
            published.generation > before_generation && published.reload == ReloadState::Idle
        })
    });

    let after = lock_recover(&graph.inner);
    let published = after.published.as_ref().unwrap();
    assert_eq!(published.fingerprint, before_fp, "semantic graph identity stayed equal");
    assert_eq!(published.generation, before_generation + 1, "a full build still published");
    assert_eq!(
        graph.project_reload_published.load(Ordering::SeqCst),
        graph.project_reload_requested.load(Ordering::SeqCst),
        "the full publication acknowledges the captured durable request",
    );
}

