/// force a graph reload or mark the whole search collection.
#[test]
fn nested_analyzer_config_does_not_trigger_project_reload() {
    use crate::change_hub::{ChangeEntry, ChangeKind};

    let dir = tempdir().unwrap();
    let workspace = dir.path().to_path_buf();
    let nested = workspace.join("subdir/bsl-analyzer.toml");
    fs::create_dir_all(nested.parent().unwrap()).unwrap();
    fs::write(&nested, "[source]\nroot = \".\"\n").unwrap();
    let engine: super::SharedSearchEngine = Arc::new(Mutex::new(None));
    let graph = crate::graph::GraphState::for_workspace(workspace);
    let entry = ChangeEntry {
        canonical: nested.clone(),
        raw: nested,
        kind: ChangeKind::MaybeChanged,
        seq: 1,
    };

    SharedState::apply_search_drift(&engine, &[entry], false, &graph);

    assert_eq!(graph.status(), crate::graph::GraphStatus::Idle);
}

